input.command:
cd /tmp/claude-0/-home-user/da0086de-3b20-57a1-97ca-069a78e742e3/scratchpad/klar-eval/r3-sonnet-b2/A4-T9-implicit-sonnet-0/acme-design-tokens
for b in $(jq -r '.backgrounds|keys[]' tokens-system.json); do BG=$(jq -r ".backgrounds[\"$b\"]" tokens-system.json)
for f in $(jq -r '.foregrounds|keys[]' tokens-system.json); do FG=$(jq -r ".foregrounds[\"$f\"]" tokens-system.json)
[ "$FG" = "$BG" ] && { echo "$f on $b: identical, skip"; continue; }
if O=$(klar contrast "$FG" "$BG" -q); then g=""; else g=" (OUT OF GAMUT)"; fi
printf "%s %s on %s %s: %s%s\n" "$f" "$FG" "$b" "$BG" "$O" "$g"
if awk -v c="$O" 'BEGIN{exit (c>=4.5)?1:0}'; then
 R=$(klar find "$BG" "$FG" --target 4.5 --json); echo "   $(jq -c '{adj:.adjustedColor,ok:.actualContrast,success,reason,deltaE,resolvableBy}' <<<"$R")"
fi
done; done

